INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "李唐", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化元年条所见人物：李唐。", "biography": null, "status": "draft", "id": "14230c1b-7bbe-54b2-b825-82d22aa61bde"}, {"name": "蔡结", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化元年条所见人物：蔡结。", "biography": null, "status": "draft", "id": "d29aa4ee-fda2-50c5-9d8e-d8ae03486eb9"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "葛从周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的葛从周，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "26557449-8ad3-53a2-9cda-77849bf316c9"}, {"name": "贺德伦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化二年条所见人物：贺德伦。", "biography": null, "status": "draft", "id": "18281df5-a215-5501-b35d-effaa3bb9fd5"}, {"name": "李嗣昭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“梁军围攻潞州，晋军出兵救援”中为守城者。", "biography": null, "status": "draft", "id": "7ebbec0f-f2d1-52fd-a1c8-d4feeef63d83"}, {"name": "李孝璋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "本版《资治通鉴》卷261光化二年条记为泽州刺史李孝璋；与《旧五代史》同役所记李存璋是否同人待核。", "biography": null, "status": "draft", "id": "94905c49-5da9-5613-a987-9de754cd80f4"}, {"name": "符存审", "aliases": ["李存审", "符存"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：符存审。", "biography": null, "status": "draft", "id": "5cb2699c-0840-5cde-b42a-ad5f2eef0a71"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "孟迁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：孟迁。", "biography": null, "status": "draft", "id": "b79a34bf-fa33-5615-b855-09c35628a57c"}, {"name": "王师范", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：王师范。", "biography": null, "status": "draft", "id": "85e4cc92-ce18-53c7-9bab-49ca198da0c3"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "台濛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：台濛。", "biography": null, "status": "draft", "id": "7de43550-c1ce-51b9-bf23-dc637131efc5"}, {"name": "王绾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化二年条所见人物：王绾。", "biography": null, "status": "draft", "id": "f7ea1041-daa8-5429-bf17-3e6523d3d418"}, {"name": "朱友谦", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为接纳者。", "biography": null, "status": "draft", "id": "bb5525ef-bfa1-507f-94d5-52e443535f7d"}, {"name": "李璠（陕州）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化二年条所见人物：李璠（陕州）。", "biography": null, "status": "draft", "id": "254cf729-b7c0-5b63-9317-d5c147c8c598"}, {"name": "赵匡凝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：赵匡凝。", "biography": null, "status": "draft", "id": "6b36d7ae-95ad-5b6e-80f2-8b5dbb6d8450"}, {"name": "李琼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：李琼。", "biography": null, "status": "draft", "id": "778953c5-1675-5fe6-bcec-c96d85e327be"}, {"name": "陈彦谦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化元年条所见人物：陈彦谦。", "biography": null, "status": "draft", "id": "f347e9c2-13d1-5a7c-a4b4-6f979ed01e76"}, {"name": "鲁景仁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261光化元年条所见人物：鲁景仁。", "biography": null, "status": "draft", "id": "5d83590c-5388-51c2-b201-fcd7be3ae6bd"}, {"name": "罗绍威", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为劝进者。", "biography": null, "status": "draft", "id": "3d7be803-d4ea-5c59-b9d9-5f0d314c4623"}]'::jsonb)
